@layer theme, base, components, utilities;
@import 'tailwindcss/theme.css' layer(theme);
@import 'tailwindcss/preflight.css' layer(base);
@import 'tailwindcss/utilities.css';

@import '@spartan-ng/brain/hlm-tailwind-preset.css';
/* You can add global styles to this file, and also import other style files */

/*
 * Hero Ops Console palette (prototype/capstone-build-spec.md, "Theme palette").
 * Each role is mapped onto the spartan token it plays. Note that spartan's
 * --accent is the subtle hover surface, not the action colour (--primary).
 */
:root {
  color-scheme: light;

  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';

  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --radius: 0.625rem;

  /* action / primary */
  --primary: #d8891a;
  --primary-foreground: #ffffff;
  /* page and text */
  --background: #f6f7fa;
  --foreground: #1b1e2b;
  /* card / popover */
  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;
  /* muted surface */
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  /* subtle hover background */
  --accent: #eef0f6;
  --accent-foreground: #1b1e2b;
  --destructive: #e5484d;
  /* border / input */
  --border: #e4e7ef;
  --input: #e4e7ef;
  /* focus ring: amber at 35% */
  --ring: #d8891a59;

  /* navigation rail: dark in both themes */
  --sidebar: #1e2233;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #d8891a;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #2a2f45;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #2a2f45;
  --sidebar-ring: #d8891a59;

  /* semantic: these carry meaning and are separate from the accent */
  --success: #2fb574;
  --success-foreground: #ffffff;
  --warning: #e4802b;
  --warning-foreground: #1b1e2b;
  --info: #4f7cf0;
  --info-foreground: #ffffff;
}

:root.dark {
  color-scheme: dark;

  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);

  /* action / primary */
  --primary: #f5b843;
  --primary-foreground: #241a05;
  /* page and text */
  --background: #0e1018;
  --foreground: #eceef6;
  /* card / popover */
  --card: #171a26;
  --card-foreground: #eceef6;
  --popover: #171a26;
  --popover-foreground: #eceef6;
  /* muted surface */
  --secondary: #1e2231;
  --secondary-foreground: #eceef6;
  --muted: #1e2231;
  --muted-foreground: #9aa0b4;
  /* subtle hover background */
  --accent: #1e2231;
  --accent-foreground: #eceef6;
  --destructive: #f2585d;
  /* border / input */
  --border: #272b3b;
  --input: #272b3b;
  /* focus ring: amber at 40% */
  --ring: #f5b84366;

  /* navigation rail: dark in both themes */
  --sidebar: #10121c;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #f5b843;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #20263c;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #20263c;
  --sidebar-ring: #f5b84366;

  /* semantic: these carry meaning and are separate from the accent */
  --success: #3ecb84;
  --success-foreground: #0e1018;
  --warning: #f0983f;
  --warning-foreground: #1b1e2b;
  --info: #6f97f6;
  --info-foreground: #0e1018;
}

@theme inline {
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

